-- DRAFT: descriptive registry only; NOT a source of authorization.
-- Reconcile with existing registries before adding this table.
begin;
create table public.lifecycle_permission_contract (
  id text primary key,
  phase text not null,
  view_name text not null,
  function_name text not null,
  actor_labels text not null,
  resource_scope text not null,
  gate_kind text not null check (gate_kind in ('owner','relationship','capability')),
  authority_boundary text not null,
  enforcement_reference text not null,
  database_duty text not null,
  evidence_status text not null default 'specified'
    check (evidence_status in ('specified','source-inspected','integration-verified'))
);
alter table public.lifecycle_permission_contract enable row level security;
revoke all on public.lifecycle_permission_contract from public, anon, authenticated;
grant select on public.lifecycle_permission_contract to authenticated;
create policy "signed-in accounts read descriptive contracts"
  on public.lifecycle_permission_contract for select to authenticated using (true);
comment on table public.lifecycle_permission_contract is
  'Non-sensitive descriptive lifecycle contracts. Does not grant permissions. No person, tenant approval, secret or protected operational data belongs here.';
commit;
